def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'

    # In the final round, defection is strictly dominant and has no future cost.
    if n >= 99:
        return 'D'

    last_me, last_opp = history[-1]

    opp_c = 0
    opp_d = 0
    my_d = 0

    opp_def5 = 0
    opp_def10 = 0
    my_def5 = 0

    seen_my_D = 0
    opp_C_after_my_D = 0

    seen_my_C = 0
    opp_D_after_my_C = 0

    for i in range(n):
        a, b = history[i]

        if b == 'C':
            opp_c += 1
        else:
            opp_d += 1

        if a == 'D':
            my_d += 1

        dist = n - i
        if dist <= 5:
            if b == 'D':
                opp_def5 += 1
            if a == 'D':
                my_def5 += 1

        if dist <= 10 and b == 'D':
            opp_def10 += 1

        if i > 0:
            prev_a = history[i - 1][0]
            if prev_a == 'D':
                seen_my_D += 1
                if b == 'C':
                    opp_C_after_my_D += 1
            else:
                seen_my_C += 1
                if b == 'D':
                    opp_D_after_my_C += 1

    # Pseudo-likelihood that opponent cooperates after one of our defections.
    pC_after_D = (opp_C_after_my_D + 1.0) / (seen_my_D + 2.0)

    opp_D_streak = 0
    for i in range(n - 1, -1, -1):
        if history[i][1] == 'D':
            opp_D_streak += 1
        else:
            break

    unprov_D_streak = 0
    for i in range(n - 1, -1, -1):
        if history[i][0] == 'C' and history[i][1] == 'D':
            unprov_D_streak += 1
        else:
            break

    # Classify opponent as unreliable/hostile enough to mostly defect.
    if n <= 8:
        untrustworthy = (opp_d >= max(3, n - 1)) or (opp_D_streak >= 3)
    elif n <= 20:
        untrustworthy = (opp_d * 2 >= n) or (opp_def5 >= 4)
    else:
        untrustworthy = (
            (opp_d * 5 >= n * 2)
            or (opp_def10 >= 7)
            or (seen_my_C >= 5 and opp_D_after_my_C * 5 >= seen_my_C * 2)
        )

    if last_opp == 'D':
        if last_me == 'D':
            # Mutual defection: usually try to restore cooperation unless they
            # look like a persistent defector.
            if untrustworthy or opp_c == 0 or opp_D_streak >= 3 or opp_d * 2 > n:
                return 'D'
            return 'C'

        # They defected while we cooperated. If this is punishment for a recent
        # D by us and they are otherwise cooperative, cooperate to de-escalate.
        if my_def5 > 0 and opp_c * 5 >= n * 3 and unprov_D_streak <= 1:
            return 'C'

        # Punish clearly untrustworthy, stubborn, or late-game exploitative D.
        if (
            opp_c == 0
            or untrustworthy
            or unprov_D_streak >= 2
            or opp_D_streak >= 3
            or (n >= 90 and my_d == 0)
        ):
            return 'D'

        return 'D'

    # Opponent cooperated last.
    if last_me == 'D':
        # They did not punish our last defection. Exploit only if evidence says
        # they are soft; otherwise return to cooperation to avoid cycles.
        if opp_d == 0:
            return 'D'

        if not untrustworthy:
            if (
                opp_c * 10 >= n * 8
                and opp_def10 <= 4
                and pC_after_D >= 0.75
            ):
                return 'D'

            if (
                n >= 90
                and opp_c * 5 >= n * 4
                and opp_def10 <= 5
                and pC_after_D >= 0.65
            ):
                return 'D'

        return 'C'

    # Mutual cooperation. Stay cooperative by default, but defect against
    # opponents that have repeatedly tolerated our defections.
    if (
        not untrustworthy
        and seen_my_D >= 1
        and opp_C_after_my_D >= 2
        and pC_after_D >= 0.75
        and opp_c * 10 >= n * 8
        and opp_def10 <= 3
    ):
        return 'D'

    return 'C'
